// Final safeguard for contribution monetary inputs.
//
// The redesigned Record Contribution modal is generated by a Vite source
// transform. Its old HTML number constraints used min=1 + step=500, which made
// ordinary values such as TZS 75,000 fail native browser validation because the
// valid sequence became 1, 501, 1001, ... 74,501, 75,001.
//
// Checkpoint's API/FY rules remain responsible for financial validation. The
// browser should only require a non-negative whole-TZS amount.
export function checkpointContributionAmountInputFix() {
  return {
    name: 'checkpoint-contribution-amount-input-fix',
    enforce: 'pre',
    transform(code, id) {
      if (!id.replaceAll('\\', '/').endsWith('/src/views/Contributions.jsx')) return null;

      let next = code;

      // Redesigned single-contribution modal.
      next = next.replace(
        'min="1"\n                step="500"',
        'min="0"\n                step="1"',
      );

      // Existing bulk/edit contribution amount fields should also accept any
      // whole-TZS value instead of imposing an artificial 1,000-TZS increment.
      next = next.replaceAll('step="1000"', 'step="1"');

      return next === code ? null : { code: next, map: null };
    },
  };
}
